-- one rule per kind of document in each client
CREATE UNIQUE INDEX IF NOT EXISTS ZC_DocControl_Kind ON ZC_DocControl (AD_Client_ID, DocBaseType) WHERE IsActive='Y';
-- one line per cost centre and account in a budget
CREATE UNIQUE INDEX IF NOT EXISTS ZC_BudgetLine_Key ON ZC_BudgetLine (ZC_Budget_ID, C_Activity_ID, Account_ID);
